import {oralTestWave} from './oral-retell.mjs';
export const roleplayDirections="Now it is your time to role-play part of the conversation. Choose the role you want to play and start your role-play.";
export function roleplayHTML({count=3,legacy=false,saveDelay=100,uploadFailure=false,mixed=false,existing=false,partnerFirst=false,partnerPauseAt=-1,choiceDelay=0}={}){
  const script=Array.from({length:count*2},(_,i)=>({speaker:(i+(partnerFirst?1:0))%2?'Mark':'Kate',text:i%2?'Here is the next reply '+i+'.':'This is my next sentence '+i+'.'}));
  return `<!doctype html><html><head><meta charset="utf-8"><style>body{font:16px Arial;margin:20px}.swiper-slide:not(.swiper-slide-active){display:none}.role-list .role{display:inline-block;margin:20px;padding:25px;border:1px solid #ccc;cursor:pointer}.list-item-review{display:flex;align-items:center;gap:12px;margin:10px}.list-item-review.active{background:#eee}.score{border:1px dashed #ccc;min-width:45px}.score.hide{visibility:hidden}.role-text-wrapper{display:flex;gap:15px}.control-box .record-seat,.audio-play-wrapper{display:inline-block;padding:12px;cursor:pointer}.pause-circle-player{height:30px;width:30px;cursor:pointer}.pause-circle-player:not(.active){visibility:hidden}.record-seat svg{width:35px;height:35px}footer{margin-top:20px}</style></head><body>
  <header><div class="pc-break-crumb"><span class="pc-break-crumb-text">Offline book</span><span class="pc-break-crumb-text">A difficult day</span><span class="pc-break-crumb-text">Conversation</span></div><div class="pc-header-tab-activity">Conversation 1</div><div class="pc-task pc-header-task-activity">Oral practice</div></header>
  <main class="pc-main-container"><div class="question-role-play"><div class="layout-container"><div class="abs-direction">${roleplayDirections}</div><div class="role-play-wrapper"><div class="swiper-container"><div class="swiper-slide swiper-slide-active" id="choose"><div class="role-list"><div class="role" id="role-a"><svg id="icon-A"></svg><label class="label"><svg class="radio"></svg><span>Kate</span></label></div><div class="role" id="role-b"><svg id="icon-B"></svg><label class="label">Mark</label></div></div></div><div class="swiper-slide" id="dialogue"></div></div></div></div></div></main><footer class="question-common-course-page"></footer>
  <script>
  window.roleChoices=0;window.starts=0;window.pauses=0;window.stops=[];window.duplicates=0;window.speakers=0;window.replays=0;window.requests=0;window.saved=[];window.submitted=false;window.recording=false;window.finished=false;window.uploading=false;
  const input=${legacy?'constraints=>new Promise((resolve,reject)=>navigator.webkitGetUserMedia(constraints,resolve,reject))':'navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices)'},cachedInput=input;
  const lines=${JSON.stringify(script)},audioURL='data:audio/wav;base64,${oralTestWave(.2).toString('base64')}',play='M661.8980157 473 L442 350 Z',stop='M464.5438957 383.16853991h-47v284zM606 383h-47v284z';let running=false,index=-1,recorder,stream,player,generation=0;
  const rows=()=>[...document.querySelectorAll('.list-item-review')];
  const render=()=>{
    document.querySelector('#choose').classList.remove('swiper-slide-active');const slide=document.querySelector('#dialogue');slide.classList.add('swiper-slide-active');slide.innerHTML='<div class="role-reply"><div class="top-tit">Step 1. Choose a role: Kate</div><div class="control-box"><div class="audio-play-wrapper" id="speaker">示范音频</div><div class="record-seat" id="start"><svg><path d="M10 10L20 20"/></svg></div><div class="audio-play-wrapper audio-replay-wrapper" id="replay">回放</div><audio></audio></div><div class="role-play-quiz"><div class="list-box">'+lines.map((line,i)=>'<div class="list-item-review"><svg class="pause-circle-player"><path d="'+play+'"/></svg><div class="score'+(line.speaker!=='Kate'?' hide':'')+'"></div><div class="role-text-wrapper"><div class="role">'+line.speaker+'</div><div class="text"><div class="reply-controller"><div class="sentence"><div>'+line.text+'</div></div></div></div></div></div>').join('')+'</div></div>${mixed?'<textarea></textarea>':''}</div>';
    player=slide.querySelector('audio');player.onended=()=>{if(running){index++;next();}};document.querySelector('#speaker').onclick=()=>window.speakers++;document.querySelector('#replay').onclick=()=>window.replays++;
    document.querySelector('#start').onclick=()=>{if(running){generation++;running=false;window.pauses++;window.recording=false;player.pause();if(recorder?.state==='recording')recorder.stop();rows().forEach(row=>{row.classList.remove('active');row.querySelector('svg').classList.remove('active');});return;}window.starts++;running=true;index=0;next();};
    rows().forEach((row,i)=>row.querySelector('svg').onclick=()=>{if(!running||!window.recording||i!==index){window.duplicates++;return;}window.stops.push(i);window.recording=false;recorder.stop();});
  };
  const next=async()=>{
    const localGeneration=generation;rows().forEach(row=>{row.classList.remove('active');row.querySelector('svg').classList.remove('active');row.querySelector('path').setAttribute('d',play);});
    if(index>=lines.length){running=false;window.finished=true;document.querySelector('footer').innerHTML='<button>提交</button>';document.querySelector('footer button').onclick=()=>{window.submitted=true;document.querySelector('main').innerHTML='<h2>答题小结</h2><p>共${count}道题，主观题${count}道</p><p>已作答 (${count}/${count}) 未作答 (0/${count})</p>';document.querySelector('footer').innerHTML='';};return;}
    const row=rows()[index];row.classList.add('active');if(lines[index].speaker!=='Kate'){player.src=audioURL;await player.play();if(index===${partnerPauseAt})player.pause();return;}
    row.querySelector('svg').classList.add('active');await new Promise(resolve=>setTimeout(resolve,120));if(!running||localGeneration!==generation)return;
    try{window.requests++;stream=await cachedInput({audio:true});if(!running||localGeneration!==generation){stream.getTracks().forEach(track=>track.stop());return;}let chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=event=>chunks.push(event.data);const current=index;recorder.onstop=async()=>{
      stream.getTracks().forEach(track=>track.stop());if(!running||localGeneration!==generation)return;window.uploading=true;await new Promise(resolve=>setTimeout(resolve,${saveDelay}));if(!running||localGeneration!==generation)return;
      if(${uploadFailure}){const error=document.createElement('div');error.setAttribute('role','alert');error.textContent='录音上传失败';document.body.append(error);return;}
      const blob=new Blob(chunks,{type:recorder.mimeType});window.saved.push({index:current,bytes:blob.size});row.querySelector('.score').textContent='0';window.uploading=false;index++;next();};recorder.start();window.recording=true;row.querySelector('path').setAttribute('d',stop);
    }catch(error){const alert=document.createElement('div');alert.setAttribute('role','alert');alert.textContent='录音失败 '+error.name;document.body.append(alert);}
  };
  document.querySelector('#role-a').onclick=()=>{window.roleChoices++;if(${choiceDelay}>0)setTimeout(render,${choiceDelay});else render();};document.querySelector('#role-b').onclick=()=>{window.wrongRole=true;};
  ${existing?'render();rows().filter((_,i)=>lines[i].speaker==="Kate").forEach(row=>row.querySelector(".score").textContent="0");index=lines.length;next();':''}
  </script></body></html>`;
}
